import { createChart, getECModel } from '../../core/utHelper';

interface Problem {
    label: string;
    kind: string;
    coord: number;
    lo: number;
    hi: number;
    all: number[];
}

function checkCartesian(chart: any, label: string, out: Problem[]) {
    const model = getECModel(chart);
    const gridComp = model.getComponent('grid', 0) as any;
    if (!gridComp) {
        return;
    }
    const rect = gridComp.coordinateSystem.getRect();
    ['xAxis', 'yAxis'].forEach(function (axisName) {
        let idx = 0;
        for (;; idx++) {
            const axisModel = model.getComponent(axisName, idx) as any;
            if (!axisModel) {
                break;
            }
            const axis = axisModel.axis;
            const horiz = axisName === 'xAxis';
            const gLo = (horiz ? rect.x : rect.y) - 1e-6;
            const gHi = (horiz ? rect.x + rect.width : rect.y + rect.height) + 1e-6;
            const ext = axis.getExtent();
            const eLo = Math.min(axis.toGlobalCoord(ext[0]), axis.toGlobalCoord(ext[1])) - 1e-6;
            const eHi = Math.max(axis.toGlobalCoord(ext[0]), axis.toGlobalCoord(ext[1])) + 1e-6;

            const sets: [string, number[]][] = [];
            sets.push(['tick', axis.getTicksCoords().map((t: any) => axis.toGlobalCoord(t.coord))]);
            sets.push(['splitLine', axis.getTicksCoords({
                tickModel: axisModel.getModel('splitLine'), clamp: true
            }).map((t: any) => axis.toGlobalCoord(t.coord))]);
            sets.push(['splitArea', axis.getTicksCoords({
                tickModel: axisModel.getModel('splitArea'), clamp: true
            }).map((t: any) => axis.toGlobalCoord(t.coord))]);
            const minor: number[] = [];
            axis.getMinorTicksCoords().forEach((g: any[]) =>
                g.forEach((t: any) => minor.push(axis.toGlobalCoord(t.coord))));
            sets.push(['minor', minor]);

            sets.forEach(function (pair) {
                const kind = pair[0];
                const coords = pair[1];
                for (let i = 0; i < coords.length; i++) {
                    const c = coords[i];
                    if (!isFinite(c) || c < gLo || c > gHi || c < eLo || c > eHi) {
                        out.push({
                            label: label + ' ' + axisName + idx,
                            kind: kind + (c < gLo || c > gHi ? '/GRID' : '/EXTENT'),
                            coord: c, lo: gLo, hi: gHi,
                            all: coords.map((x: number) => +x.toFixed(2))
                        });
                        break;
                    }
                }
            });
        }
    });
}

function run(label: string, option: any, actions: any[], out: Problem[]) {
    const chart = createChart({ width: 400, height: 300 });
    try {
        chart.setOption(option);
    }
    catch (e) {
        out.push({ label: label + ' SETOPTION THROW ' + e, kind: 'throw', coord: 0, lo: 0, hi: 0, all: [] });
        chart.dispose();
        return;
    }
    checkCartesian(chart, label + ' [init]', out);
    actions.forEach(function (a, ai) {
        try {
            chart.dispatchAction(a);
        }
        catch (e) {
            out.push({ label: label + ' action' + ai + ' THROW ' + e, kind: 'throw', coord: 0, lo: 0, hi: 0, all: [] });
            return;
        }
        checkCartesian(chart, label + ' [' + JSON.stringify(a) + ']', out);
    });
    chart.dispose();
}

function report(out: Problem[]) {
    const lines = out.map(p => p.kind + ' | ' + p.label + ' | coord=' + (+p.coord.toFixed(3))
        + ' grid=[' + (+p.lo.toFixed(3)) + ',' + (+p.hi.toFixed(3)) + '] all=' + JSON.stringify(p.all));
    console.log('=== PROBLEMS ' + out.length + ' ===\n' + lines.slice(0, 60).join('\n'));
}

describe('tmp tick overflow A1: value/log/time axes with dataZoom', function () {

    const zoomActions = [
        { type: 'dataZoom', start: 20, end: 60 },
        { type: 'dataZoom', start: 71, end: 100 },
        { type: 'dataZoom', start: 0, end: 8 },
        { type: 'dataZoom', start: 33.3333, end: 77.7777 },
        { type: 'dataZoom', start: 49.5, end: 50.5 },
        { type: 'dataZoom', startValue: 3.5, endValue: 17.3 }
    ];

    it('value axis', function () {
        const out: Problem[] = [];
        const data: number[][] = [];
        for (let i = 0; i < 30; i++) {
            data.push([i, (i * 7) % 23 + 1]);
        }
        const filterModes = ['filter', 'weakFilter', 'empty', 'none'];
        const variants: any[] = [];
        filterModes.forEach(fm =>
            [false, true].forEach(inverse =>
                [false, true].forEach(minor =>
                    [undefined, { min: 0, max: 29 }, { scale: true }, { minInterval: 1 }].forEach(extra =>
                        variants.push({ fm, inverse, minor, extra })))));

        variants.forEach(function (v) {
            const label = 'value ' + JSON.stringify(v);
            run(label, {
                animation: false,
                xAxis: Object.assign({
                    type: 'value', inverse: v.inverse,
                    minorTick: { show: v.minor }, minorSplitLine: { show: v.minor },
                    splitLine: { show: true }, splitArea: { show: true }
                }, v.extra || {}),
                yAxis: { type: 'value', minorTick: { show: v.minor } },
                dataZoom: [{ type: 'inside', xAxisIndex: 0, filterMode: v.fm }],
                series: [{ type: 'line', data: data }]
            }, zoomActions, out);
        });
        report(out);
        expect(true).toBe(true);
    });

    it('log axis', function () {
        const out: Problem[] = [];
        const data: number[][] = [];
        for (let i = 0; i < 30; i++) {
            data.push([Math.pow(10, i / 6 + 0.13), (i * 7) % 23 + 1]);
        }
        ['filter', 'weakFilter', 'empty', 'none'].forEach(function (fm) {
            [false, true].forEach(function (minor) {
                run('log fm=' + fm + ' minor=' + minor, {
                    animation: false,
                    xAxis: {
                        type: 'log', minorTick: { show: minor }, minorSplitLine: { show: minor },
                        splitLine: { show: true }, splitArea: { show: true }
                    },
                    yAxis: {},
                    dataZoom: [{ type: 'inside', xAxisIndex: 0, filterMode: fm }],
                    series: [{ type: 'line', data: data }]
                }, zoomActions, out);
            });
        });
        report(out);
        expect(true).toBe(true);
    });

    it('time axis', function () {
        const out: Problem[] = [];
        const data: any[] = [];
        const base = +new Date(2020, 0, 1);
        for (let i = 0; i < 40; i++) {
            data.push([base + i * 3600 * 1000 * 13, (i * 7) % 23 + 1]);
        }
        ['filter', 'weakFilter', 'empty', 'none'].forEach(function (fm) {
            [false, true].forEach(function (minor) {
                run('time fm=' + fm + ' minor=' + minor, {
                    animation: false,
                    xAxis: {
                        type: 'time', minorTick: { show: minor }, minorSplitLine: { show: minor },
                        splitLine: { show: true }, splitArea: { show: true }
                    },
                    yAxis: {},
                    dataZoom: [{ type: 'inside', xAxisIndex: 0, filterMode: fm }],
                    series: [{ type: 'line', data: data }]
                }, zoomActions, out);
            });
        });
        report(out);
        expect(true).toBe(true);
    });

    it('y axis zoom / both axes', function () {
        const out: Problem[] = [];
        const data: number[][] = [];
        for (let i = 0; i < 30; i++) {
            data.push([i, (i * 7) % 23 + 1]);
        }
        ['filter', 'weakFilter', 'empty', 'none'].forEach(function (fm) {
            run('yzoom fm=' + fm, {
                animation: false,
                xAxis: { type: 'value', minorTick: { show: true } },
                yAxis: { type: 'value', minorTick: { show: true }, splitLine: { show: true } },
                dataZoom: [
                    { type: 'inside', yAxisIndex: 0, filterMode: fm },
                    { type: 'inside', xAxisIndex: 0, filterMode: fm }
                ],
                series: [{ type: 'line', data: data }]
            }, [
                { type: 'dataZoom', dataZoomIndex: 0, start: 20, end: 60 },
                { type: 'dataZoom', dataZoomIndex: 1, start: 30, end: 44 },
                { type: 'dataZoom', dataZoomIndex: 0, start: 0, end: 3 }
            ], out);
        });
        report(out);
        expect(true).toBe(true);
    });

    it('category axis with minor/split and custom values', function () {
        const out: Problem[] = [];
        const cats: string[] = [];
        const vals: number[] = [];
        for (let i = 0; i < 30; i++) {
            cats.push('c' + i);
            vals.push(i % 7 + 1);
        }
        [undefined, ['c2', 'c9', 'c20', 'c29']].forEach(function (cv, ci) {
            [true, false].forEach(function (bg) {
                ['filter', 'weakFilter', 'empty', 'none'].forEach(function (fm) {
                    run('cat cv=' + ci + ' bg=' + bg + ' fm=' + fm, {
                        animation: false,
                        xAxis: {
                            type: 'category', data: cats, boundaryGap: bg,
                            axisTick: { customValues: cv },
                            splitLine: { show: true }, splitArea: { show: true }
                        },
                        yAxis: {},
                        dataZoom: [{ type: 'inside', filterMode: fm }],
                        series: [{ type: 'bar', data: vals }]
                    }, zoomActions, out);
                });
            });
        });
        report(out);
        expect(true).toBe(true);
    });
});

