 34	const NORMALIZED_EXTENT = [0, 1] as [number, number];
 35	
 36	interface TickCoord {
 37	    coord: number;
 38	    // That is `scaleTick.value`.
 39	    tickValue?: ScaleTick['value'];
 40	}
