 42	/**
 43	 * Base class of Axis.
 44	 */
 45	class Axis {
 46	
 47	    /**
 48	     * Axis type
 49	     *  - 'category'
 50	     *  - 'value'
 51	     *  - 'time'
 52	     *  - 'log'
 53	     */
 54	    type: OptionAxisType;
 55	
 56	    // Axis dimension. Such as 'x', 'y', 'z', 'angle', 'radius'.
 57	    readonly dim: DimensionName;
 58	
 59	    // Axis scale
 60	    scale: Scale;
 61	
 62	    private _extent: [number, number];
 63	
 64	    // Injected outside
 65	    model: AxisBaseModel;
 66	    onBand: CategoryAxisBaseOption['boundaryGap'] = false;
 67	    inverse: AxisBaseOption['inverse'] = false;
 68	
 69	
 70	    constructor(dim: DimensionName, scale: Scale, extent: [number, number]) {
 71	        this.dim = dim;
 72	        this.scale = scale;
 73	        this._extent = extent || [0, 0];
 74	    }
 75	
 76	    /**
 77	     * If axis extent contain given coord
 78	     */
 79	    contain(coord: number): boolean {
 80	        const extent = this._extent;
 81	        const min = Math.min(extent[0], extent[1]);
 82	        const max = Math.max(extent[0], extent[1]);
 83	        return coord >= min && coord <= max;
 84	    }
 85	
 86	    /**
 87	     * If axis extent contain given data
 88	     */
 89	    containData(data: ScaleDataValue): boolean {
 90	        return this.scale.contain(data);
 91	    }
 92	
 93	    /**
 94	     * Get coord extent.
 95	     */
 96	    getExtent(): [number, number] {
 97	        return this._extent.slice() as [number, number];
 98	    }
 99	
100	    /**
101	     * Get precision used for formatting
102	     */
103	    getPixelPrecision(dataExtent?: [number, number]): number {
104	        return getPixelPrecision(
105	            dataExtent || this.scale.getExtent(),
106	            this._extent
107	        );
108	    }
109	
110	    /**
111	     * Set coord extent
112	     */
113	    setExtent(start: number, end: number): void {
114	        const extent = this._extent;
115	        extent[0] = start;
116	        extent[1] = end;
117	    }
118	
119	    /**
120	     * Convert data to coord. Data is the rank if it has an ordinal scale
121	     */
122	    dataToCoord(data: ScaleDataValue, clamp?: boolean): number {
123	        let extent = this._extent;
124	        const scale = this.scale;
125	        data = scale.normalize(data);
126	
127	        if (this.onBand && scale.type === 'ordinal') {
128	            extent = extent.slice() as [number, number];
129	            fixExtentWithBands(extent, (scale as OrdinalScale).count());
130	        }
131	
132	        return linearMap(data, NORMALIZED_EXTENT, extent, clamp);
133	    }
134	
135	    /**
136	     * Convert coord to data. Data is the rank if it has an ordinal scale
137	     */
138	    coordToData(coord: number, clamp?: boolean): number {
139	        let extent = this._extent;
140	        const scale = this.scale;
141	
142	        if (this.onBand && scale.type === 'ordinal') {
143	            extent = extent.slice() as [number, number];
144	            fixExtentWithBands(extent, (scale as OrdinalScale).count());
145	        }
146	
147	        const t = linearMap(coord, extent, NORMALIZED_EXTENT, clamp);
148	
149	        return this.scale.scale(t);
150	    }
151	
152	    /**
153	     * Convert pixel point to data in axis
154	     */
155	    pointToData(point: number[], clamp?: boolean): number {
156	        // Should be implemented in derived class if necessary.
157	        return;
158	    }
159	
160	    /**
161	     * Different from `zrUtil.map(axis.getTicks(), axis.dataToCoord, axis)`,
162	     * `axis.getTicksCoords` considers `onBand`, which is used by
163	     * `boundaryGap:true` of category axis and splitLine and splitArea.
164	     * @param opt.tickModel default: axis.model.getModel('axisTick')
165	     * @param opt.clamp If `true`, the first and the last
166	     *        tick must be at the axis end points. Otherwise, clip ticks
167	     *        that outside the axis extent.
168	     */
169	    getTicksCoords(opt?: {
170	        tickModel?: Model,
171	        clamp?: boolean
172	    }): TickCoord[] {
173	        opt = opt || {};
174	
175	        const tickModel = opt.tickModel || this.getTickModel();
176	        const result = createAxisTicks(this, tickModel as AxisBaseModel);
177	        const ticks = result.ticks;
178	
179	        const ticksCoords = map(ticks, function (tickVal) {
180	            return {
181	                coord: this.dataToCoord(
182	                    this.scale.type === 'ordinal'
183	                        ? (this.scale as OrdinalScale).getRawOrdinalNumber(tickVal)
184	                        : tickVal
185	                ),
186	                tickValue: tickVal
187	            };
188	        }, this);
189	
190	        const alignWithLabel = tickModel.get('alignWithLabel');
191	
192	        fixOnBandTicksCoords(
193	            this, ticksCoords, alignWithLabel, opt.clamp
194	        );
195	
196	        return ticksCoords;
197	    }
198	
199	    getMinorTicksCoords(): TickCoord[][] {
200	        if (this.scale.type === 'ordinal') {
201	            // Category axis doesn't support minor ticks
202	            return [];
203	        }
204	
205	        const minorTickModel = this.model.getModel('minorTick');
206	        let splitNumber = minorTickModel.get('splitNumber');
207	        // Protection.
208	        if (!(splitNumber > 0 && splitNumber < 100)) {
209	            splitNumber = 5;
210	        }
211	        const minorTicks = this.scale.getMinorTicks(splitNumber);
212	        const minorTicksCoords = map(minorTicks, function (minorTicksGroup) {
213	            return map(minorTicksGroup, function (minorTick) {
214	                return {
215	                    coord: this.dataToCoord(minorTick),
216	                    tickValue: minorTick
217	                };
218	            }, this);
219	        }, this);
220	        return minorTicksCoords;
221	    }
222	
223	    getViewLabels(): ReturnType<typeof createAxisLabels>['labels'] {
224	        return createAxisLabels(this).labels;
225	    }
226	
227	    getLabelModel(): Model<AxisBaseOption['axisLabel']> {
228	        return this.model.getModel('axisLabel');
229	    }
230	
231	    /**
232	     * Notice here we only get the default tick model. For splitLine
233	     * or splitArea, we should pass the splitLineModel or splitAreaModel
234	     * manually when calling `getTicksCoords`.
235	     * In GL, this method may be overridden to:
236	     * `axisModel.getModel('axisTick', grid3DModel.getModel('axisTick'));`
237	     */
238	    getTickModel(): Model {
239	        return this.model.getModel('axisTick');
240	    }
241	
242	    /**
243	     * Get width of band
244	     */
245	    getBandWidth(): number {
246	        const axisExtent = this._extent;
247	        const dataExtent = this.scale.getExtent();
248	
249	        let len = dataExtent[1] - dataExtent[0] + (this.onBand ? 1 : 0);
250	        // Fix #2728, avoid NaN when only one data.
251	        len === 0 && (len = 1);
252	
253	        const size = Math.abs(axisExtent[1] - axisExtent[0]);
254	
255	        return Math.abs(size) / len;
256	    }
257	
258	    /**
259	     * Get axis rotate, by degree.
260	     */
261	    getRotate: () => number;
262	
263	    /**
264	     * Only be called in category axis.
265	     * Can be overridden, consider other axes like in 3D.
266	     * @return Auto interval for cateogry axis tick and label
267	     */
268	    calculateCategoryInterval(): ReturnType<typeof calculateCategoryInterval> {
269	        return calculateCategoryInterval(this);
270	    }
271	
272	}
273	
274	function fixExtentWithBands(extent: [number, number], nTick: number): void {
275	    const size = extent[1] - extent[0];
276	    const len = nTick;
277	    const margin = size / len / 2;
278	    extent[0] += margin;
279	    extent[1] -= margin;
280	}
281	
282	// If axis has labels [1, 2, 3, 4]. Bands on the axis are
283	// |---1---|---2---|---3---|---4---|.
284	// So the displayed ticks and splitLine/splitArea should between
285	// each data item, otherwise cause misleading (e.g., split tow bars
286	// of a single data item when there are two bar series).
287	// Also consider if tickCategoryInterval > 0 and onBand, ticks and
288	// splitLine/spliteArea should layout appropriately corresponding
289	// to displayed labels. (So we should not use `getBandWidth` in this
290	// case).
291	function fixOnBandTicksCoords(
292	    axis: Axis, ticksCoords: TickCoord[], alignWithLabel: boolean, clamp: boolean
293	) {
294	    const ticksLen = ticksCoords.length;
295	
296	    if (!axis.onBand || alignWithLabel || !ticksLen) {
297	        return;
298	    }
299	
300	    const axisExtent = axis.getExtent();
301	    let last;
302	    let diffSize;
303	    if (ticksLen === 1) {
304	        ticksCoords[0].coord = axisExtent[0];
305	        last = ticksCoords[1] = {coord: axisExtent[1]};
306	    }
307	    else {
308	        const crossLen = ticksCoords[ticksLen - 1].tickValue - ticksCoords[0].tickValue;
309	        const shift = (ticksCoords[ticksLen - 1].coord - ticksCoords[0].coord) / crossLen;
310	
311	        each(ticksCoords, function (ticksItem) {
312	            ticksItem.coord -= shift / 2;
313	        });
314	
315	        const dataExtent = axis.scale.getExtent();
316	        diffSize = 1 + dataExtent[1] - ticksCoords[ticksLen - 1].tickValue;
317	
318	        last = {coord: ticksCoords[ticksLen - 1].coord + shift * diffSize};
319	
320	        ticksCoords.push(last);
321	    }
322	
323	    const inverse = axisExtent[0] > axisExtent[1];
324	
325	    // Handling clamp.
326	    if (littleThan(ticksCoords[0].coord, axisExtent[0])) {
327	        clamp ? (ticksCoords[0].coord = axisExtent[0]) : ticksCoords.shift();
328	    }
329	    if (clamp && littleThan(axisExtent[0], ticksCoords[0].coord)) {
330	        ticksCoords.unshift({coord: axisExtent[0]});
331	    }
332	    if (littleThan(axisExtent[1], last.coord)) {
333	        clamp ? (last.coord = axisExtent[1]) : ticksCoords.pop();
334	    }
335	    if (clamp && littleThan(last.coord, axisExtent[1])) {
336	        ticksCoords.push({coord: axisExtent[1]});
337	    }
338	
339	    function littleThan(a: number, b: number): boolean {
340	        // Avoid rounding error cause calculated tick coord different with extent.
341	        // It may cause an extra unnecessary tick added.
342	        a = round(a);
343	        b = round(b);
344	        return inverse ? a > b : a < b;
345	    }
346	}
347	
348	export default Axis;

