 63	export function createAxisLabels(axis: Axis): {
 64	    labels: {
 65	        level?: number,
 66	        formattedLabel: string,
 67	        rawLabel: string,
 68	        tickValue: number
 69	    }[],
 70	    labelCategoryInterval?: number
 71	} {
 72	    const custom = makeAxisLabelsFromCustomValues(axis);
 73	    if (custom) {
 74	        return custom;
 75	    }
 76	    // Only ordinal scale support tick interval
 77	    return axis.type === 'category'
 78	        ? makeCategoryLabels(axis)
 79	        : makeRealNumberLabels(axis);
