 82	/**
 83	 * @param {module:echats/coord/Axis} axis
 84	 * @param {module:echarts/model/Model} tickModel For example, can be axisTick, splitLine, splitArea.
 85	 * @return {Object} {
 86	 *     ticks: Array.<number>
 87	 *     tickCategoryInterval: number
 88	 * }
 89	 */
 90	export function createAxisTicks(axis: Axis, tickModel: AxisBaseModel): {
 91	    ticks: number[],
 92	    tickCategoryInterval?: number
 93	} {
 94	    const customValues = (tickModel as unknown as Model<AxisTickOption>).get('customValues');
 95	    if (customValues) {
 96	        return { ticks: parseCustomValues(axis, customValues) };
 97	    }
 98	    // Only ordinal scale support tick interval
 99	    return axis.type === 'category'
100	        ? makeCategoryTicks(axis, tickModel)
101	        : {ticks: zrUtil.map(axis.scale.getTicks(), tick => tick.value) };
102	}
