104	/**
105	 * Parse the user specified `customValues` to the inner tick values
106	 * (the ordinal number for ordinal scale, the numeric value otherwise),
107	 * and discard the values that are out of the axis extent.
108	 */
109	function parseCustomValues(axis: Axis, customValues: (number | string | Date)[]): number[] {
110	    const scale = axis.scale;
111	    const extent = scale.getExtent();
112	    const result: number[] = [];
113	    zrUtil.each(customValues, function (val) {
114	        const tickValue = scale.parse(val);
115	        // NaN is filtered out by the comparison as well.
116	        if (tickValue >= extent[0] && tickValue <= extent[1]) {
117	            result.push(tickValue);
118	        }
119	    });
120	    return result;
121	}
