123	/**
124	 * Make labels at the `axisLabel.customValues` if specified,
125	 * otherwise return `null` to keep the default behavior.
126	 */
127	function makeAxisLabelsFromCustomValues(axis: Axis): ReturnType<typeof createAxisLabels> {
128	    const labelModel = axis.getLabelModel();
129	    const customValues = labelModel.get('customValues');
130	    if (!customValues) {
131	        return null;
132	    }
133	    // Labels are always made by the normal label formatter, so that,
134	    // for example, time axis labels are formatted as expected.
135	    const labelFormatter = makeLabelFormatter(axis);
136	    return {
137	        labels: zrUtil.map(parseCustomValues(axis, customValues), function (tickValue, idx) {
138	            const tickObj = { value: tickValue };
139	            return {
140	                formattedLabel: labelFormatter(tickObj, idx),
141	                rawLabel: axis.scale.getLabel(tickObj),
142	                tickValue: tickValue
143	            };
144	        })
145	    };
146	}
