148	function makeCategoryLabels(axis: Axis) {
149	    const labelModel = axis.getLabelModel();
150	    const result = makeCategoryLabelsActually(axis, labelModel);
151	
152	    return (!labelModel.get('show') || axis.scale.isBlank())
153	        ? {labels: [], labelCategoryInterval: result.labelCategoryInterval}
154	        : result;
