157	function makeCategoryLabelsActually(axis: Axis, labelModel: Model<AxisBaseOption['axisLabel']>) {
158	    const labelsCache = getListCache(axis, 'labels');
159	    const optionLabelInterval = getOptionCategoryInterval(labelModel);
160	    const result = listCacheGet(labelsCache, optionLabelInterval as CacheKey);
161	
162	    if (result) {
163	        return result;
164	    }
165	
166	    let labels;
167	    let numericLabelInterval;
168	
169	    if (zrUtil.isFunction(optionLabelInterval)) {
170	        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
171	    }
172	    else {
173	        numericLabelInterval = optionLabelInterval === 'auto'
174	            ? makeAutoCategoryInterval(axis) : optionLabelInterval;
175	        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
176	    }
177	
178	    // Cache to avoid calling interval function repeatedly.
179	    return listCacheSet(labelsCache, optionLabelInterval as CacheKey, {
180	        labels: labels, labelCategoryInterval: numericLabelInterval
181	    });
182	}
183	
184	function makeCategoryTicks(axis: Axis, tickModel: AxisBaseModel) {
185	    const ticksCache = getListCache(axis, 'ticks');
186	    const optionTickInterval = getOptionCategoryInterval(tickModel);
187	    const result = listCacheGet(ticksCache, optionTickInterval as CacheKey);
188	
189	    if (result) {
190	        return result;
191	    }
192	
193	    let ticks: number[];
194	    let tickCategoryInterval;
195	
196	    // Optimize for the case that large category data and no label displayed,
197	    // we should not return all ticks.
198	    if (!tickModel.get('show') || axis.scale.isBlank()) {
199	        ticks = [];
200	    }
201	
202	    if (zrUtil.isFunction(optionTickInterval)) {
203	        ticks = makeLabelsByCustomizedCategoryInterval(axis, optionTickInterval, true);
204	    }
205	    // Always use label interval by default despite label show. Consider this
206	    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
207	    // labels. `splitLine` and `axisTick` should be consistent in this case.
208	    else if (optionTickInterval === 'auto') {
209	        const labelsResult = makeCategoryLabelsActually(axis, axis.getLabelModel());
210	        tickCategoryInterval = labelsResult.labelCategoryInterval;
211	        ticks = zrUtil.map(labelsResult.labels, function (labelItem) {
212	            return labelItem.tickValue;
213	        });
214	    }
215	    else {
216	        tickCategoryInterval = optionTickInterval;
217	        ticks = makeLabelsByNumericCategoryInterval(axis, tickCategoryInterval, true);
218	    }
219	
220	    // Cache to avoid calling interval function repeatedly.
221	    return listCacheSet(ticksCache, optionTickInterval as CacheKey, {
222	        ticks: ticks, tickCategoryInterval: tickCategoryInterval
223	    });
