243	// axis is created each time during a ec process, so we do not need to clear cache.
244	function getListCache(axis: Axis, prop: 'ticks'): InnerStore['ticks'];
245	function getListCache(axis: Axis, prop: 'labels'): InnerStore['labels'];
246	function getListCache(axis: Axis, prop: 'ticks' | 'labels') {
247	    // Because key can be a function, and cache size always is small, we use array cache.
248	    return inner(axis)[prop] || (inner(axis)[prop] = []);
