251	function listCacheGet<T>(cache: InnerTickLabelCache<T>, key: CacheKey): T {
252	    for (let i = 0; i < cache.length; i++) {
253	        if (cache[i].key === key) {
254	            return cache[i].value;
255	        }
256	    }
257	}
