271	/**
272	 * Calculate interval for category axis ticks and labels.
273	 * To get precise result, at least one of `getRotate` and `isHorizontal`
274	 * should be implemented in axis.
275	 */
276	export function calculateCategoryInterval(axis: Axis) {
277	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
278	    const labelFormatter = makeLabelFormatter(axis);
279	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
280	
281	    const ordinalScale = axis.scale as OrdinalScale;
282	    const ordinalExtent = ordinalScale.getExtent();
283	    // Providing this method is for optimization:
284	    // avoid generating a long array by `getTicks`
285	    // in large category data case.
286	    const tickCount = ordinalScale.count();
287	
288	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
289	        return 0;
290	    }
291	
292	    let step = 1;
293	    // Simple optimization. Empirical value: tick count should less than 40.
294	    if (tickCount > 40) {
295	        step = Math.max(1, Math.floor(tickCount / 40));
296	    }
297	    let tickValue = ordinalExtent[0];
298	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
299	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
300	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
301	
302	    let maxW = 0;
303	    let maxH = 0;
304	
305	    // Caution: Performance sensitive for large category data.
306	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
307	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
308	        let width = 0;
309	        let height = 0;
310	
311	        // Not precise, do not consider align and vertical align
312	        // and each distance from axis line yet.
313	        const rect = textContain.getBoundingRect(
314	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
315	        );
316	        // Magic number
317	        width = rect.width * 1.3;
318	        height = rect.height * 1.3;
319	
320	        // Min size, void long loop.
321	        maxW = Math.max(maxW, width, 7);
322	        maxH = Math.max(maxH, height, 7);
323	    }
324	
325	    let dw = maxW / unitW;
326	    let dh = maxH / unitH;
327	    // 0/0 is NaN, 1/0 is Infinity.
328	    isNaN(dw) && (dw = Infinity);
329	    isNaN(dh) && (dh = Infinity);
330	    let interval = Math.max(0, Math.floor(Math.min(dw, dh)));
331	
332	    const cache = inner(axis.model);
