import Axis from '../../../../src/coord/Axis';
import OrdinalScale from '../../../../src/scale/Ordinal';
import IntervalScale from '../../../../src/scale/Interval';
import LogScale from '../../../../src/scale/Log';
import Model from '../../../../src/model/Model';
import { AxisBaseModel } from '../../../../src/coord/AxisBaseModel';
import { round } from '../../../../src/util/number';
import { createChart, getECModel } from '../../core/utHelper';

type TC = { coord: number, tickValue?: number };

function makeAxis(opt: {
    onBand?: boolean,
    interval?: any,
    alignWithLabel?: boolean,
    extent?: [number, number],
    count?: number
}): Axis {
    const cats: string[] = [];
    for (let i = 0; i < (opt.count == null ? 5 : opt.count); i++) {
        cats.push(String.fromCharCode(97 + i));
    }
    const scale = new OrdinalScale({ ordinalMeta: cats });
    const axis = new Axis('x', scale, (opt.extent || [0, 300]).slice() as [number, number]);
    axis.type = 'category';
    axis.onBand = opt.onBand !== false;
    axis.model = new Model({
        type: 'category',
        axisLabel: {},
        axisTick: {
            show: true,
            interval: opt.interval == null ? 0 : opt.interval,
            alignWithLabel: !!opt.alignWithLabel
        }
    }) as unknown as AxisBaseModel;
    return axis;
}

// ---- replica of src/coord/Axis.ts fixOnBandTicksCoords (CURRENT code) ----
function fixOnBand(axis: Axis, ticksCoords: TC[], alignWithLabel: boolean, clamp: boolean, variant: string) {
    const ticksLen = ticksCoords.length;
    if (!axis.onBand || alignWithLabel || !ticksLen) {
        return;
    }
    const axisExtent = axis.getExtent();
    let last: TC;
    let diffSize;
    if (ticksLen === 1) {
        ticksCoords[0].coord = axisExtent[0];
        last = ticksCoords[1] = { coord: axisExtent[1] };
    }
    else {
        const crossLen = ticksCoords[ticksLen - 1].tickValue - ticksCoords[0].tickValue;
        const shift = (ticksCoords[ticksLen - 1].coord - ticksCoords[0].coord) / crossLen;
        ticksCoords.forEach(function (ticksItem) {
            ticksItem.coord -= shift / 2;
        });
        const dataExtent = axis.scale.getExtent();
        diffSize = 1 + dataExtent[1] - ticksCoords[ticksLen - 1].tickValue;
        last = { coord: ticksCoords[ticksLen - 1].coord + shift * diffSize };
        ticksCoords.push(last);
    }

    const inverse = axisExtent[0] > axisExtent[1];
    function littleThan(a: number, b: number): boolean {
        a = round(a);
        b = round(b);
        return inverse ? a > b : a < b;
    }

    // ==== candidate fix A: drop every tick fully outside the extent ====
    if (variant === 'A') {
        while (ticksCoords.length > 1 && !littleThan(axisExtent[0], ticksCoords[1].coord)) {
            ticksCoords.shift();
        }
        while (ticksCoords.length > 1
            && !littleThan(ticksCoords[ticksCoords.length - 2].coord, axisExtent[1])
        ) {
            ticksCoords.pop();
        }
        last = ticksCoords[ticksCoords.length - 1];
    }

    if (littleThan(ticksCoords[0].coord, axisExtent[0])) {
        clamp ? (ticksCoords[0].coord = axisExtent[0]) : ticksCoords.shift();
    }
    if (clamp && littleThan(axisExtent[0], ticksCoords[0].coord)) {
        ticksCoords.unshift({ coord: axisExtent[0] });
    }
    if (littleThan(axisExtent[1], last.coord)) {
        clamp ? (last.coord = axisExtent[1]) : ticksCoords.pop();
    }
    if (clamp && littleThan(last.coord, axisExtent[1])) {
        ticksCoords.push({ coord: axisExtent[1] });
    }
}

/**
 * variant:
 *  'cur' = current src behaviour
 *  'A'   = fix inside fixOnBandTicksCoords (loop the clamp removal)
 *  'B'   = fix in getTicksCoords: filter ticks outside scale extent first
 */
function ticksCoordsOf(axis: Axis, ticks: number[], clamp: boolean, variant: string): number[] {
    let used = ticks;
    if (variant === 'B') {
        const se = axis.scale.getExtent();
        used = ticks.filter(t => t >= se[0] && t <= se[1]);
    }
    const ticksCoords: TC[] = used.map(function (tickVal) {
        return {
            coord: axis.dataToCoord((axis.scale as OrdinalScale).getRawOrdinalNumber(tickVal)),
            tickValue: tickVal
        };
    });
    fixOnBand(axis, ticksCoords, !!axis.model.getModel('axisTick').get('alignWithLabel'), clamp, variant);
    return ticksCoords.map(t => +t.coord.toFixed(4));
}

function outside(coords: number[], extent: number[]): number[] {
    const lo = Math.min(extent[0], extent[1]) - 1e-8;
    const hi = Math.max(extent[0], extent[1]) + 1e-8;
    return coords.filter(c => !(c >= lo && c <= hi));
}

