                        + '\n     ' + line.join('\n     '));
                });
            });
        });
        console.log('--- A2 candidate fixes ---\n' + rows.join('\n'));
        expect(true).toBe(true);
    });

    it('non-zoomed (fresh) ticks are identical under all variants', function () {
        const rows: string[] = [];
        const cases: any[] = [
            { name: 'onBand,interval0', o: {} },
