            { name: 'onBand,interval0,count=1', o: { count: 1 } },
            { name: 'onBand,count=2', o: { count: 2 } },
            { name: 'onBand,alignWithLabel', o: { alignWithLabel: true } },
            { name: 'onBand=false', o: { onBand: false } },
            { name: 'inverse', o: { extent: [300, 0] } },
            { name: 'inverse,interval2', o: { extent: [300, 0], interval: 2 } }
        ];
        cases.forEach(function (c) {
            [false, true].forEach(function (clamp) {
                const res: string[] = [];
                ['cur', 'A', 'B'].forEach(function (variant) {
                    const axis = makeAxis(c.o);
                    const ticks = makeAxis(c.o).getTicksCoords().map(t => t.tickValue)
                        .filter(v => v != null) as number[];
                    res.push(variant + '=' + JSON.stringify(ticksCoordsOf(axis, ticks, clamp, variant)));
                });
                const same = res[0].slice(4) === res[1].slice(2) && res[0].slice(4) === res[2].slice(2);
                rows.push((same ? 'SAME  ' : 'DIFF  ') + c.name + ' clamp=' + clamp + ' ' + res.join(' | '));
            });
        });
        console.log('--- A2 fresh-tick equivalence ---\n' + rows.join('\n'));
        expect(true).toBe(true);
    });

    it('minor ticks vs scale extent (value / log)', function () {
        const rows: string[] = [];
        // interval scale
        const s = new IntervalScale();
        s.setExtent(0, 100);
