        const ax = new Axis('x', s, [0, 300]);
        ax.type = 'value';
        ax.model = new Model({ minorTick: { splitNumber: 5 } }) as unknown as AxisBaseModel;
        rows.push('interval ticks=' + JSON.stringify(s.getTicks().map(t => t.value)));
        rows.push('interval minor(before)=' + JSON.stringify(ax.getMinorTicksCoords()
            .map(g => g.map(t => +t.coord.toFixed(2)))));
