import { createChart, getECModel } from '../../core/utHelper';
import { createAxisTicks } from '../../../../src/coord/axisTickLabelBuilder';

/**
 * For every axis of a freshly rendered chart, check whether any tick returned by
 * `createAxisTicks` lies outside `scale.getExtent()`.
 * If none does, filtering ticks by the scale extent inside `Axis#getTicksCoords`
 * is a no-op for real (non-stale) rendering.
 */
function probe(chart: any, label: string, out: string[]) {
    const model = getECModel(chart);
    const comps = ['xAxis', 'yAxis', 'singleAxis', 'angleAxis', 'radiusAxis'];
    comps.forEach(function (compName) {
        for (let idx = 0; ; idx++) {
            const axisModel = model.getComponent(compName, idx) as any;
            if (!axisModel) {
                break;
            }
            const axis = axisModel.axis;
            if (!axis) {
                break;
            }
            const se = axis.scale.getExtent();
            ['axisTick', 'splitLine', 'splitArea', 'minorSplitLine'].forEach(function (tm) {
                const tickModel = axisModel.getModel(tm);
                let ticks: number[];
                try {
                    ticks = createAxisTicks(axis, tickModel).ticks;
                }
                catch (e) {
                    out.push('THROW ' + label + ' ' + compName + idx + ' ' + tm + ' ' + e);
                    return;
                }
                const bad = ticks.filter(t => !(t >= se[0] && t <= se[1]));
                if (bad.length) {
                    out.push('TICK-OUTSIDE-SCALE-EXTENT ' + label + ' ' + compName + idx + ' ' + tm
                        + ' scaleExtent=' + JSON.stringify(se)
                        + ' bad=' + JSON.stringify(bad)
                        + ' allTicks=' + JSON.stringify(ticks.slice(0, 12)));
                }
                // Also record the pixel result vs the axis extent, for completeness.
                const ext = axis.getExtent();
                const lo = Math.min(ext[0], ext[1]) - 1e-6;
                const hi = Math.max(ext[0], ext[1]) + 1e-6;
                [false, true].forEach(function (clamp) {
                    const coords = axis.getTicksCoords({ tickModel: tickModel, clamp: clamp })
                        .map((t: any) => t.coord);
                    const badC = coords.filter((c: number) => !isFinite(c) || c < lo || c > hi);
                    if (badC.length) {
                        out.push('COORD-OUTSIDE-AXIS-EXTENT ' + label + ' ' + compName + idx + ' ' + tm
                            + ' clamp=' + clamp + ' extent=' + JSON.stringify(ext)
                            + ' bad=' + JSON.stringify(badC.map((c: number) => +c.toFixed(3))));
                    }
                });
            });
        }
    });
}

function run(label: string, option: any, actions: any[], out: string[]) {
    const chart = createChart({ width: 420, height: 320 });
    try {
        chart.setOption(option);
    }
    catch (e) {
        out.push('SETOPTION THROW ' + label + ' ' + e);
        chart.dispose();
        return;
    }
    probe(chart, label + '[init]', out);
    actions.forEach(function (a) {
        try {
            chart.dispatchAction(a);
        }
        catch (e) {
            out.push('ACTION THROW ' + label + ' ' + e);
            return;
        }
        probe(chart, label + '[' + JSON.stringify(a) + ']', out);
    });
    chart.dispose();
}

