describe('tmp A4', function () {

    it('labels are stale too (same cache mechanism)', function () {
        const scale = new OrdinalScale({ ordinalMeta: ['a', 'b', 'c', 'd', 'e'] });
        const axis = new Axis('x', scale, [0, 300]);
        axis.type = 'category';
        axis.onBand = true;
        axis.model = new Model({
            type: 'category', axisLabel: { interval: 0 }, axisTick: { show: true, interval: 0 }
        }) as unknown as AxisBaseModel;
        const before = axis.getViewLabels().map(l => ({
            v: l.tickValue, c: +axis.dataToCoord((axis.scale as OrdinalScale).getRawOrdinalNumber(l.tickValue)).toFixed(2)
        }));
        axis.scale.setExtent(2, 4);
        const after = axis.getViewLabels().map(l => ({
            v: l.tickValue, c: +axis.dataToCoord((axis.scale as OrdinalScale).getRawOrdinalNumber(l.tickValue)).toFixed(2)
        }));
        console.log('--- A4 labels ---\nbefore=' + JSON.stringify(before) + '\nafter =' + JSON.stringify(after)
            + '\nlabelCoordsOutside=' + JSON.stringify(after.filter(o => o.c < 0 || o.c > 300)));
        expect(true).toBe(true);
    });

    it('non-ordinal scale.getTicks() vs its own extent (float-tolerance risk)', function () {
        const bad: string[] = [];
        let checked = 0;
        const mk = (kind: string) => kind === 'interval' ? new IntervalScale()
            : kind === 'log' ? new LogScale() : new TimeScale({ locale: null as any, useUTC: false } as any);
        ['interval', 'log', 'time'].forEach(function (kind) {
            const ranges: [number, number][] = kind === 'log'
                ? [[1, 1000], [0.003, 7.7], [333333.99999999953, 777777], [1e-7, 3e-3], [2, 3]]
                : kind === 'time'
                ? [[+new Date(2021, 0, 1), +new Date(2021, 0, 3)],
                   [+new Date(2021, 0, 1, 3, 17, 5, 123), +new Date(2021, 0, 1, 3, 19, 5, 321)],
                   [+new Date(1999, 5, 1), +new Date(2031, 5, 1)]]
                : [[0, 100], [-3.3, 21.7], [1 / 3, 2 / 3], [1e-9, 3e-9], [1e12, 1e12 + 7], [5, 5]];
            ranges.forEach(function (r) {
                [3, 5, 8].forEach(function (sn) {
                    const s: any = mk(kind);
                    s.setExtent(r[0], r[1]);
                    try {
                        s.calcNiceExtent({ splitNumber: sn, fixMin: true, fixMax: true });
                    }
                    catch (e) { /* ignore */ }
                    const ext = s.getExtent();
                    const ticks = s.getTicks().map((t: any) => t.value);
                    checked++;
                    const strictlyOut = ticks.filter((t: number) => t < ext[0] || t > ext[1]);
                    const roundedOut = ticks.filter((t: number) => round(t) < round(ext[0]) || round(t) > round(ext[1]));
                    if (strictlyOut.length || roundedOut.length) {
                        bad.push(kind + ' extent=' + JSON.stringify(ext) + ' sn=' + sn
                            + ' strictlyOutside=' + JSON.stringify(strictlyOut)
                            + ' roundedOutside=' + JSON.stringify(roundedOut));
                    }
                });
            });
        });
        console.log('--- A4 non-ordinal getTicks vs extent (' + checked + ' cases) ---\n'
            + (bad.length ? bad.join('\n') : 'none outside'));
        expect(true).toBe(true);
    });
});

